import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Navigate using browser back after filling contact form', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Which service are you interested in', 'Test Automation')
  await opFill(page, 'Message', 'Need help with automated regression suite')
  await opClick(page, 'link', 'Test Automation')
  await opPress(page, 'Backspace')
  await opSeen(page, 'heading', 'Contact')
})
